from itertools import combinations

def triples_sum_to_zero(l: list):
    """
    triples_sum_to_zero receives a list of integers as its parameter.
    It returns True if there exist three unique numbers in the list that sum up to zero, otherwise it returns False.

    This function should efficiently find the triplets without using excessive computational resources.
    """
    if len(l) < 3:
        return False

    for triplet in combinations(l, 3):
        if sum(triplet) == 0:
            return True

